import { Injectable } from '@nestjs/common';
import {
  BlobServiceClient,
  generateBlobSASQueryParameters,
  BlobSASPermissions,
  SASProtocol,
  ContainerClient,
} from '@azure/storage-blob';

import { v4 as uuidv4 } from 'uuid';

function generateRandomText() {
  const lines = [
    'Lorem ipsum dolor sit amet.',
    'Generated by Node.js on Azure!',
    'Each line is random.',
    `Timestamp: ${new Date().toISOString()}`,
  ];
  return lines.join('\n');
}

@Injectable()
export class AppService {
  private blobServiceClient: BlobServiceClient;
  private containerName = 'tempfiles';
  private accountName = process.env.AZURE_STORAGE_ACCOUNT_NAME!; // optional
  private connectionString = process.env.AZURE_STORAGE_CONNECTION_STRING!;
  private containerClient: ContainerClient;

  constructor() {
    this.blobServiceClient = BlobServiceClient.fromConnectionString(
      this.connectionString,
    );
    this.containerClient = this.blobServiceClient.getContainerClient(
      this.containerName,
    );
  }

  async uploadRandomFile(contentType = 'text/plain') {
    const dateStr = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    // eslint-disable-next-line @typescript-eslint/no-unsafe-call
    const blobName = `${dateStr}-${uuidv4()}.txt`;
    const text = generateRandomText();
    const buffer = Buffer.from(text, 'utf-8');
    const blobClient = this.containerClient.getBlockBlobClient(blobName);
    await blobClient.uploadData(buffer, {
      blobHTTPHeaders: { blobContentType: contentType },
    });
    console.log(`✅ Uploaded blob: ${blobName}`);
    console.log(`📎 URL: ${blobClient.url}`);
    return blobClient.url;
  }

  async upload(buffer: Buffer, blobName: string, contentType?: string) {
    const containerClient = this.blobServiceClient.getContainerClient(
      this.containerName,
    );
    const blobClient = containerClient.getBlockBlobClient(blobName);
    await blobClient.uploadData(buffer, {
      blobHTTPHeaders: {
        blobContentType: contentType || 'application/octet-stream',
      },
    });
    return blobClient.url;
  }

  generateTempLink(blobName: string, minutes = 15) {
    const containerClient = this.blobServiceClient.getContainerClient(
      this.containerName,
    );
    const blobClient = containerClient.getBlockBlobClient(blobName);
    const expiresOn = new Date(new Date().valueOf() + minutes * 60 * 1000);

    const sas = generateBlobSASQueryParameters(
      {
        containerName: this.containerName,
        blobName,
        permissions: BlobSASPermissions.parse('r'),
        expiresOn,
        protocol: SASProtocol.Https,
      },
      // eslint-disable-next-line @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-member-access
      (this.blobServiceClient as any).credential, // uses connection string credential
    ).toString();

    return `${blobClient.url}?${sas}`;
  }
}
